import React from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip
} from '@mui/material';
import { Edit as EditIcon, Delete as DeleteIcon } from '@mui/icons-material';

// Обновленные цвета для ваших типов
const typeColors = {
  MERCH: 'primary',
  DEVICES: 'secondary',
  ACCESSORIES: 'success',
  COUPONS: 'warning',
};

export const ItemList = ({ items, onEdit, onDelete }) => {
  if (!items || items.length === 0) {
    return (
      <Paper sx={{ p: 4, textAlign: 'center' }}>
        <Typography variant="h6">No items found</Typography>
        <Typography variant="body1">Add a new item or adjust your search</Typography>
      </Paper>
    );
  }

  return (
    <TableContainer component={Paper}>
      <Table sx={{ minWidth: 650 }} aria-label="Items table">
        <TableHead>
          <TableRow>
            <TableCell>Name</TableCell>
            <TableCell>Type</TableCell>
            {/* ... остальные колонки ... */}
          </TableRow>
        </TableHead>
        <TableBody>
          {items.map((item) => (
            <TableRow key={item.item_id}>
              {/* ... другие ячейки ... */}
              <TableCell>
                <Chip
                  label={item.type?.toLowerCase() || 'unknown'}
                  color={typeColors[item.type] || 'default'}
                  sx={{ textTransform: 'capitalize' }}
                />
              </TableCell>
              {/* ... другие ячейки ... */}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};
